1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<title>Portfolio board</title>
6	<style>
7	  :root{--bg:#12141a;--panel:#1a1d26;--panel2:#20242f;--line:#2c3140;--ink:#e6e9f0;
8	        --dim:#98a0b3;--faint:#6b7385;--accent:#7c8cff;--bad:#ff8b8b}
9	  *{box-sizing:border-box}
10	  body{margin:0;background:var(--bg);color:var(--ink);
11	       font:14px/1.45 ui-sans-serif,-apple-system,"Segoe UI",system-ui,sans-serif}
12	  header{padding:12px 16px;border-bottom:1px solid var(--line);display:flex;gap:12px;align-items:center}
13	  h1{font-size:15px;margin:0;font-weight:650}
14	  .tabs{display:flex;gap:6px;margin-left:auto}
15	  .tab{background:var(--panel);border:1px solid var(--line);color:var(--dim);
16	       padding:5px 14px;border-radius:7px;cursor:pointer}
17	  .tab.on{background:var(--accent);border-color:var(--accent);color:#0d0f14;font-weight:600}
18	  button.plain{background:var(--panel);border:1px solid var(--line);color:var(--dim);
19	               padding:5px 12px;border-radius:7px;cursor:pointer}
20	  .cols{display:flex;gap:10px;padding:14px;overflow-x:auto;align-items:flex-start}
21	  .col{background:var(--panel);border:1px solid var(--line);border-radius:11px;
22	       min-width:224px;width:224px;flex:0 0 auto}
23	  .col>h2{margin:0;padding:10px 11px;font-size:11px;letter-spacing:.9px;text-transform:uppercase;
24	          color:var(--dim);border-bottom:1px solid var(--line);display:flex;justify-content:space-between}
25	  .drop{padding:9px;display:flex;flex-direction:column;gap:8px;min-height:70px}
26	  .col.over{outline:2px solid var(--accent);outline-offset:-2px}
27	  .inbox{background:#1b1726;border-color:#3a3050}
28	  .card{background:var(--panel2);border:1px solid var(--line);border-radius:9px;
29	        padding:9px 10px;cursor:grab;position:relative}
30	  .card.open{cursor:default}
31	  .card h3{margin:0 0 5px;font-size:13px;font-weight:600;padding-right:74px;word-break:break-word}
32	  .st{position:absolute;top:6px;right:6px;font-size:10px;padding:3px 6px;border-radius:99px;
33	      background:#0d0f14;color:var(--dim);border:1px solid var(--line);font-family:inherit}
34	  .card p{margin:0;color:var(--dim);font-size:12px;
35	          display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
36	  .bar{height:3px;background:#000;border-radius:99px;margin-top:8px;overflow:hidden}
37	  .bar i{display:block;height:100%;background:var(--accent)}
38	  .rk{color:var(--faint);font-size:10px;margin-top:4px}
39	  .panel{margin-top:9px;padding-top:9px;border-top:1px solid var(--line);
40	         display:flex;flex-direction:column;gap:6px}
41	  .panel label{font-size:10px;letter-spacing:.7px;text-transform:uppercase;color:var(--faint)}
42	  .panel textarea,.panel input{width:100%;background:#0d0f14;color:var(--ink);
43	        border:1px solid var(--line);border-radius:6px;padding:6px 7px;font:12px/1.4 inherit}
44	  .panel .missing{border-color:#7a3030}
45	  .up{font-size:11px;color:var(--dim);background:#0d0f14;border-radius:5px;padding:5px 7px}
46	  .up b{color:var(--faint);font-weight:500}
47	  .warn{font-size:11px;color:var(--bad);background:#2a1616;border:1px solid #5a2626;
48	        border-radius:6px;padding:5px 7px}
49	  .flash{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);z-index:99;
50	         background:#2a1616;color:var(--bad);border:1px solid #5a2626;padding:8px 14px;
51	         border-radius:8px;font-size:12.5px;display:none;max-width:70vw}
52	</style>
53	</head>
54	<body>
55	<header>
56	  <h1>Portfolio board</h1>
57	  <span id="meta" style="color:var(--faint);font-size:12px"></span>
58	  <div class="tabs" id="tabs"></div>
59	  <button class="plain" id="undo">Undo</button>
60	</header>
61	<div id="app"></div>
62	<div class="flash" id="flash"></div>
63	
64	<script>
65	const TOKEN = new URLSearchParams(location.search).get("token") || "";
66	const STAGES = ["idea","grilled","spec","planned","building","shipped"];
67	const STATUSES = ["active","paused","done","dropped"];
68	const ARCHIVED = new Set(["done","dropped"]);
69	let REG = null, lane = "job", openCard = null;
70	const drafts = new Map();          // inbox name -> {purpose?, next_action?} draft edits not yet promoted
71	
72	function applyDrafts(){
73	  (REG.inbox || []).forEach(r => {
74	    const d = drafts.get(r.name);
75	    if(d) Object.assign(r, d);
76	  });
77	}
78	
79	function flash(msg){
80	  const f = document.getElementById("flash");
81	  f.textContent = msg; f.style.display = "block";
82	  clearTimeout(flash.t); flash.t = setTimeout(()=>f.style.display="none", 5000);
83	}
84	async function api(path, opts = {}){
85	  const sep = path.includes("?") ? "&" : "?";
86	  const res = await fetch(path + sep + "token=" + encodeURIComponent(TOKEN), {
87	    headers: {"Content-Type":"application/json"}, ...opts
88	  });
89	  if(!res.ok){
90	    let msg = res.statusText;
91	    try { msg = (await res.json()).error || msg; } catch {}
92	    throw new Error(msg);
93	  }
94	  return res.json();
95	}
96	function showBlocked(msg){
97	  const app = document.getElementById("app");
98	  app.textContent = "";
99	  const p = document.createElement("p");
100	  p.style.cssText = "padding:24px;color:var(--bad)";
101	  p.textContent = "Cannot load the board: " + msg;
102	  app.append(p);
103	}
104	async function load(){
105	  try {
106	    REG = await api("/api/registry");
107	    applyDrafts();
108	    render();
109	  } catch(e){
110	    flash(e.message);
111	    if(!REG) showBlocked(e.message);
112	  }
113	}
114	
115	// any failed write reloads from disk, so the board never shows a state that was not saved
116	async function write(path, payload, method = "POST"){
117	  let ok = true;
118	  try {
119	    const opts = {method};
120	    if(method !== "DELETE") opts.body = JSON.stringify(payload || {});
121	    await api(path, opts);
122	  } catch(e){
123	    ok = false;
124	    flash(e.message);
125	  }
126	  await load();          // load() handles its own errors, so a failed reload is never silent
127	  return ok;
128	}
129	
130	const idx = s => Math.max(0, STAGES.indexOf(s));
131	const live = l => REG.projects
132	  .filter(p => p.lane === l && !ARCHIVED.has(p.status))
133	  .sort((a,b) => (a.rank||1e6) - (b.rank||1e6));
134	
135	let dragged = null;
136	function card(rec, from){
137	  const open = openCard === rec.name;
138	  const d = document.createElement("div");
139	  d.className = "card" + (open ? " open" : "");
140	  d.dataset.name = rec.name;
141	  d.draggable = !open && !ARCHIVED.has(rec.status);
142	
143	  const h = document.createElement("h3"); h.textContent = rec.name;
144	  d.append(h);
145	
146	  if(from !== "inbox"){
147	    const sel = document.createElement("select");
148	    sel.className = "st";
149	    STATUSES.forEach(v => {
150	      const o = document.createElement("option");
151	      o.value = v; o.textContent = v; o.selected = v === (rec.status || "active");
152	      sel.append(o);
153	    });
154	    sel.onmousedown = e => e.stopPropagation();
155	    sel.onclick = e => e.stopPropagation();
156	    sel.onchange = e => {
157	      e.stopPropagation();
158	      write(`/api/project/${encodeURIComponent(rec.name)}`, {status: sel.value});
159	    };
160	    d.append(sel);
161	  }
162	
163	  if(!open){
164	    const p = document.createElement("p");
165	    p.textContent = rec.purpose || "— no purpose yet —";
166	    d.append(p);
167	  }
168	  if(from !== "inbox"){
169	    const b = document.createElement("div"); b.className = "bar";
170	    const i = document.createElement("i");
171	    i.style.width = ((idx(rec.stage)+1)/STAGES.length*100).toFixed(0) + "%";
172	    b.append(i);
173	    const r = document.createElement("div"); r.className = "rk";
174	    r.textContent = `#${rec.rank ?? "—"} · ${rec.stage || "unstaged"}`;
175	    d.append(b, r);
176	  }
177	  if(open) d.append(panel(rec, from));
178	
179	  d.onclick = () => { openCard = open ? null : rec.name; render(); };
180	  d.addEventListener("dragstart", e => {
181	    dragged = {rec, from};
182	    e.dataTransfer.effectAllowed = "move";
183	    e.dataTransfer.setData("text/plain", rec.name);
184	  });
185	  d.addEventListener("dragend", () => dragged = null);
186	  return d;
187	}
188	
189	function panel(rec, from){
190	  const p = document.createElement("div"); p.className = "panel";
191	  p.onclick = e => e.stopPropagation();
192	  p.onmousedown = e => e.stopPropagation();
193	
194	  const needsFields = from === "inbox";
195	  if(needsFields && (!rec.purpose || !rec.next_action)){
196	    const w = document.createElement("div"); w.className = "warn";
197	    w.textContent = "Drag onto a stage column to promote. Purpose and next action are both required first.";
198	    p.append(w);
199	  }
200	  const field = (key, label, tag) => {
201	    const l = document.createElement("label"); l.textContent = label;
202	    const el = document.createElement(tag);
203	    if(tag === "textarea") el.rows = 3;
204	    el.value = rec[key] || "";
205	    if(!el.value) el.classList.add("missing");
206	    el.oninput = () => {
207	      rec[key] = el.value;
208	      el.classList.toggle("missing", !el.value);
209	      if(from === "inbox"){
210	        const d = drafts.get(rec.name) || {};
211	        d[key] = el.value;
212	        drafts.set(rec.name, d);
213	      }
214	    };
215	    el.onchange = () => {
216	      if(from === "inbox") return;             // inbox edits are held until promotion
217	      write(`/api/project/${encodeURIComponent(rec.name)}`, {[key]: el.value});
218	    };
219	    p.append(l, el);
220	  };
221	  field("purpose", "purpose", "textarea");
222	  field("next_action", "next action", "input");
223	
224	  if(from !== "inbox"){
225	    const l = document.createElement("label"); l.textContent = "add update";
226	    const add = document.createElement("input");
227	    add.placeholder = "one line, then Enter";
228	    add.onkeydown = e => {
229	      if(e.key !== "Enter" || !add.value.trim()) return;
230	      write(`/api/project/${encodeURIComponent(rec.name)}`, {note: add.value.trim()});
231	    };
232	    p.append(l, add);
233	    (rec.updates || []).slice(0, 6).forEach(u => {
234	      const d = document.createElement("div"); d.className = "up";
235	      const b = document.createElement("b"); b.textContent = u.date + " ";
236	      d.append(b, document.createTextNode(u.note));
237	      p.append(d);
238	    });
239	    const del = document.createElement("button");
240	    del.className = "plain"; del.textContent = "Delete project";
241	    del.onclick = () => {
242	      if(confirm(`Delete "${rec.name}"? This rewrites portfolio.json.`))
243	        write(`/api/project/${encodeURIComponent(rec.name)}`, null, "DELETE");
244	    };
245	    p.append(del);
246	  }
247	  return p;
248	}
249	
250	function column(title, count, cls){
251	  const c = document.createElement("div"); c.className = "col " + (cls || "");
252	  const h = document.createElement("h2");
253	  const a = document.createElement("span"); a.textContent = title;
254	  const b = document.createElement("span"); b.textContent = count;
255	  h.append(a, b);
256	  const z = document.createElement("div"); z.className = "drop";
257	  c.append(h, z);
258	  return {col: c, zone: z};
259	}
260	
261	function dropTarget(colEl, zoneEl, stage){
262	  colEl.addEventListener("dragover", e => { e.preventDefault(); colEl.classList.add("over"); });
263	  colEl.addEventListener("dragleave", () => colEl.classList.remove("over"));
264	  colEl.addEventListener("drop", e => {
265	    e.preventDefault(); colEl.classList.remove("over");
266	    if(!dragged) return;
267	    const cards = [...zoneEl.querySelectorAll(".card")].filter(c => c.dataset.name !== dragged.rec.name);
268	    let position = cards.length;
269	    for(let i = 0; i < cards.length; i++){
270	      const r = cards[i].getBoundingClientRect();
271	      if(e.clientY < r.top + r.height/2){ position = i; break; }
272	    }
273	    const {rec, from} = dragged;
274	    if(from === "inbox"){
275	      write(`/api/inbox/${encodeURIComponent(rec.name)}/promote`,
276	            {lane, stage, position, purpose: rec.purpose || "", next_action: rec.next_action || ""})
277	        .then(ok => { if(ok) drafts.delete(rec.name); });
278	    } else {
279	      write("/api/move", {name: rec.name, lane, stage, position});
280	    }
281	  });
282	}
283	
284	function render(){
285	  const app = document.getElementById("app");
286	  app.textContent = "";
287	  const wrap = document.createElement("div"); wrap.className = "cols";
288	
289	  const inbox = REG.inbox || [];
290	  const ib = column("Inbox", inbox.length, "inbox");
291	  inbox.forEach(r => ib.zone.append(card(r, "inbox")));
292	  wrap.append(ib.col);
293	
294	  STAGES.forEach(s => {
295	    const list = live(lane).filter(p => p.stage === s);
296	    const c = column(s, list.length);
297	    list.forEach(p => c.zone.append(card(p, "board")));
298	    dropTarget(c.col, c.zone, s);
299	    wrap.append(c.col);
300	  });
301	
302	  const arch = REG.projects.filter(p => p.lane === lane && ARCHIVED.has(p.status));
303	  const ac = column("Archive", arch.length);
304	  arch.forEach(p => ac.zone.append(card(p, "board")));
305	  wrap.append(ac.col);
306	  app.append(wrap);
307	
308	  document.getElementById("meta").textContent =
309	    `${REG.projects.length} projects · ${inbox.length} inbox · ${arch.length} archived`;
310	
311	  const tabs = document.getElementById("tabs");
312	  tabs.textContent = "";
313	  ["job","side"].forEach(l => {
314	    const b = document.createElement("button");
315	    b.className = "tab" + (l === lane ? " on" : "");
316	    b.textContent = l;
317	    b.onclick = () => { lane = l; openCard = null; render(); };
318	    tabs.append(b);
319	  });
320	}
321	
322	document.getElementById("undo").onclick = () => write("/api/undo", {});
323	load();
324	</script>
325	</body>
326	</html>
