def render_pulse(vm: dict) -> str:
    job_top = vm["front_burner"].get("job") or [None]
    side_top = vm["front_burner"].get("side") or [None]
    job_top = job_top[0]
    side_top = side_top[0]

    def _fb_str(p: dict | None) -> str:
        if p is None:
            return "none"
        return f'{p["name"]} — {p.get("next_action", "")}'

    lines = [f"**Front burner** · job: {_fb_str(job_top)} · side: {_fb_str(side_top)}"]

    stale_names = []
    for lane in ("job", "side"):
        for p in vm["lanes"].get(lane, []):
            if p.get("status") == "active" and p.get("stale") and p["name"] not in stale_names:
                stale_names.append(p["name"])
    if stale_names:
        lines.append(f"⚠ Stale: {', '.join(stale_names)}")

    inbox_count = len(vm.get("ideas_inbox", []))
    if inbox_count > 0:
        lines.append(f"💡 Inbox: {inbox_count} idea(s) waiting")

    return "\n".join(lines)


